<?php
/** Quetta Workbench storage exchange: public capacity discovery with protected farmer booking. */
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_once __DIR__ . '/../includes/storage-marketplace.php';

$farmer = current_user();
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $actor = require_login(); verify_csrf(); $action = normalize_text($_POST['saved_storage_action'] ?? '', 30);
    try {
        if ($action === 'save') { save_storage_search((int) $actor['id'], (string) ($_POST['search_name'] ?? ''), storage_marketplace_filters($_POST)); flash('success', 'Storage search saved to your account.'); }
        elseif ($action === 'delete') { $searchId = filter_input(INPUT_POST, 'search_id', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); if (!$searchId) throw new RuntimeException('Choose a valid saved storage search to remove.'); delete_storage_search((int) $actor['id'], (int) $searchId); flash('success', 'Saved storage search removed.'); }
        else { throw new RuntimeException('That saved-storage action is not available.'); }
    } catch (Throwable $exception) { flash('error', $exception instanceof RuntimeException ? $exception->getMessage() : 'The saved-storage action could not be completed.'); }
    redirect('storage/index.php');
}
$filters = storage_marketplace_filters($_GET);
$storagePage = max(1, min((int) ($_GET['page'] ?? 1), 500)); $storagePageSize = 12;
$facilities = find_storage_facilities($filters, $storagePageSize, ($storagePage - 1) * $storagePageSize);
$storagePageQuery = $_GET; unset($storagePageQuery['page']);
$categories = fetch_all('SELECT id, name FROM produce_categories WHERE is_active = 1 ORDER BY name');
$districts = fetch_all('SELECT DISTINCT district FROM locations ORDER BY district');
$farmerListings = $farmer !== null && $farmer['role_slug'] === 'farmer' ? fetch_all('SELECT id, title, category_id FROM produce_listings WHERE farmer_id = :farmer AND status = "active" ORDER BY title', ['farmer' => $farmer['id']]) : [];
$savedStorageReady = saved_storage_searches_ready();
$savedStorageSearches = $farmer === null ? [] : saved_storage_searches_for_user((int) $farmer['id']);
$pageTitle = 'Cold Storage';
require __DIR__ . '/../includes/header.php';
?>
<section class="service-hero"><div class="service-hero-copy"><h1>Find storage that fits the harvest.</h1><p>Filter available capacity by crop, district, type, size, and daily price before sending a booking request.</p></div></section>
<section class="section"><div class="site-container"><div class="section-heading"><div><h2>Available cold storage</h2></div><p>Bookings remain requests until the facility provider checks compatibility, dates, and capacity.</p></div><div class="storage-discovery-layout"><aside class="storage-filter-rail"><form class="filter-panel" method="get" data-storage-filter data-endpoint="<?= e(app_url('ajax/storage/search.php')) ?>"><h2>Find suitable capacity</h2><div class="form-field"><label for="storage-category-id">Produce type</label><select id="storage-category-id" name="category_id"><option value="">All produce types</option><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>" <?= $filters['category_id'] === (int) $category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="storage-district">District</label><select id="storage-district" name="district"><option value="">All districts</option><?php foreach ($districts as $district): ?><option value="<?= e($district['district']) ?>" <?= $filters['district'] === $district['district'] ? 'selected' : '' ?>><?= e($district['district']) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="storage-type">Storage type</label><select id="storage-type" name="storage_type"><option value="">Any storage type</option><option value="cold_storage" <?= $filters['storage_type'] === 'cold_storage' ? 'selected' : '' ?>>Cold storage</option><option value="controlled_atmosphere" <?= $filters['storage_type'] === 'controlled_atmosphere' ? 'selected' : '' ?>>Controlled atmosphere</option><option value="warehouse" <?= $filters['storage_type'] === 'warehouse' ? 'selected' : '' ?>>Warehouse</option><option value="hybrid" <?= $filters['storage_type'] === 'hybrid' ? 'selected' : '' ?>>Hybrid</option></select></div><div class="form-field"><label for="storage-min-capacity">Minimum available capacity (kg)</label><input id="storage-min-capacity" name="min_capacity" type="number" min="1" step="0.01" value="<?= e((string) ($filters['min_capacity'] ?? '')) ?>"></div><div class="form-field"><label for="storage-max-price">Maximum daily price (Rs./kg)</label><input id="storage-max-price" name="max_price" type="number" min="0.01" step="0.01" value="<?= e((string) ($filters['max_price'] ?? '')) ?>"></div><div class="form-field"><label for="storage-sort">Sort storage</label><select id="storage-sort" name="sort"><option value="capacity_high" <?= $filters['sort'] === 'capacity_high' ? 'selected' : '' ?>>Most capacity</option><option value="price_low" <?= $filters['sort'] === 'price_low' ? 'selected' : '' ?>>Price: low to high</option><option value="price_high" <?= $filters['sort'] === 'price_high' ? 'selected' : '' ?>>Price: high to low</option><option value="recent" <?= $filters['sort'] === 'recent' ? 'selected' : '' ?>>Recently updated</option></select></div><div class="filter-actions"><button class="button button-primary" type="submit">Update storage</button><a class="button button-quiet" href="<?= e(app_url('storage/index.php')) ?>">Clear</a></div></form></aside><div class="storage-discovery-results"><div class="results-bar"><p data-storage-feedback aria-live="polite"><?= count($facilities) ?> storage facilit<?= count($facilities) === 1 ? 'y' : 'ies' ?> shown.</p></div><div class="service-grid" data-storage-results><?= storage_facility_cards_html($facilities, $farmer) ?></div></div></div></div></section>
<?php if ($farmer !== null && $farmer['role_slug'] === 'farmer'): ?><section class="section section-paper" id="book-storage"><div class="site-container booking-layout"><form action="<?= e(app_url('ajax/storage/book.php')) ?>" method="post" class="booking-form" data-ajax-form><h2>Reserve cold storage</h2><p>The facility provider will review the request before capacity is committed. The estimate uses its current daily price and your requested dates.</p><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><div class="booking-form-grid"><div class="form-field full"><label for="facility_id">Facility</label><select id="facility_id" name="facility_id" required><option value="">Choose a facility</option><?php foreach ($facilities as $facility): ?><option value="<?= (int) $facility['id'] ?>"><?= e($facility['name']) ?> · <?= number_format((float) $facility['available_capacity_kg'], 0) ?> kg available</option><?php endforeach;?></select></div><div class="form-field"><label for="listing_id">Your listed produce (optional)</label><select id="listing_id" name="listing_id"><option value="">Select later</option><?php foreach($farmerListings as $listing): ?><option value="<?= (int) $listing['id'] ?>"><?= e($listing['title']) ?></option><?php endforeach;?></select></div><div class="form-field"><label for="category_id">Produce type</label><select id="category_id" name="category_id" required><option value="">Choose produce</option><?php foreach($categories as $category): ?><option value="<?= (int)$category['id'] ?>"><?= e($category['name']) ?></option><?php endforeach;?></select></div><div class="form-field"><label for="quantity_kg">Quantity (kg)</label><input id="quantity_kg" name="quantity_kg" type="number" min="1" step="0.01" required></div><div class="form-field"><label for="start_date">Start date</label><input id="start_date" name="start_date" type="date" min="<?= date('Y-m-d') ?>" required></div><div class="form-field"><label for="end_date">End date</label><input id="end_date" name="end_date" type="date" min="<?= date('Y-m-d') ?>" required></div><div class="full" data-form-feedback></div><button class="button button-primary full" type="submit">Send booking request</button></div></form><aside class="booking-note"><h2>What happens next</h2><p>The provider sees requested produce, quantity, dates, and a calculated estimate. You receive an in-app notification when the request is approved, rejected, or activated.</p><ul><li>Capacity is checked against the facility’s available space.</li><li>Compatible produce is verified server-side.</li><li>Every booking status is recorded in its history.</li></ul></aside></div></section><?php endif; ?>
<?php if ($storagePage > 1 || count($facilities) === $storagePageSize): ?><nav class="result-pagination site-container" aria-label="Cold storage pages"><?php if ($storagePage > 1): ?><a class="button button-quiet" href="<?= e(app_url('storage/index.php?' . http_build_query(array_merge($storagePageQuery, ['page' => $storagePage - 1])))) ?>">Previous</a><?php endif; ?><span>Page <?= $storagePage ?></span><?php if (count($facilities) === $storagePageSize): ?><a class="button button-quiet" href="<?= e(app_url('storage/index.php?' . http_build_query(array_merge($storagePageQuery, ['page' => $storagePage + 1])))) ?>">Next</a><?php endif; ?></nav><?php endif; ?>
<?php if ($farmer === null): ?><section class="section"><div class="site-container saved-search-section"><h2>Save a storage search</h2><p>Sign in to save the capacity criteria you use often.</p><a class="button button-outline" href="<?= e(app_url('auth/login.php')) ?>">Sign in to save searches</a></div></section>
<?php elseif (!$savedStorageReady): ?><section class="section"><div class="site-container saved-search-section"><h2>Saved searches need setup</h2><p>Import <code>database/migrations/20260827_add_saved_storage_searches.sql</code> into <code>quetta_agrilink</code>, then refresh this page.</p></div></section>
<?php else: ?><section class="section"><div class="site-container saved-search-section"><h2>Save this storage search</h2><p>Keep these criteria in your account. Only you can view, apply, or remove them.</p><form method="post" class="saved-filter-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="saved_storage_action" value="save"><?php foreach (['category_id','district','storage_type','min_capacity','max_price','sort'] as $key): ?><input type="hidden" name="<?= e($key) ?>" value="<?= e((string) ($filters[$key] ?? '')) ?>"><?php endforeach; ?><div class="form-field"><label for="storage-search-name">Search name</label><input id="storage-search-name" name="search_name" maxlength="80" required placeholder="Example: Quetta apple storage"></div><button class="button button-primary" type="submit">Save search</button></form><div class="saved-filter-list"><?php if ($savedStorageSearches === []): ?><p class="saved-filter-empty">No saved storage searches yet.</p><?php else: foreach ($savedStorageSearches as $search): ?><article class="saved-filter-item"><div><strong><?= e($search['name']) ?></strong><span><?= e($search['category_name'] ?? 'All produce') ?> · <?= e($search['district'] ?? 'All districts') ?> · <?= e(str_replace('_', ' ', $search['sort_key'])) ?></span></div><div class="saved-filter-actions"><a class="button button-quiet" href="<?= e(app_url('storage/index.php?' . saved_storage_search_query($search))) ?>">Apply</a><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="saved_storage_action" value="delete"><input type="hidden" name="search_id" value="<?= (int) $search['id'] ?>"><button class="text-action" type="submit">Remove</button></form></div></article><?php endforeach; endif; ?></div></div></section><?php endif; ?>
